"use client";

import { useState, useEffect, useCallback, useMemo } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { ScrollArea } from "@/components/ui/scroll-area";
import {
  Loader2,
  Save,
  File,
  Folder,
  FolderOpen,
  FilePlus,
  FolderPlus,
  Download,
  Eye,
  Pencil,
  ChevronRight,
  Trash2,
} from "lucide-react";
import { renderMarkdown } from "./markdown";
import { createWorkspaceApi } from "./workspace-api";
import type { WorkspaceMode, WorkspaceNode, WorkspaceApi } from "./types";

export interface AgentWorkspaceProps {
  /** @deprecated 使用 id + mode="agent" */
  agentId?: string;
  /** 工作区所属 ID（agent ID 或 task ID） */
  id?: string;
  /** 工作区模式：agent（默认） | task */
  mode?: WorkspaceMode;
  /** 自定义类名 */
  className?: string;
}

export function AgentWorkspace({ agentId, id, mode = 'agent', className }: AgentWorkspaceProps) {
  const targetId = id || agentId || '';

  // 统一 API
  const api: WorkspaceApi = useMemo(() => createWorkspaceApi(mode), [mode]);

  // 文件树状态
  const [treeMap, setTreeMap] = useState<Record<string, WorkspaceNode[]>>({});
  const [expanded, setExpanded] = useState<Set<string>>(new Set());
  const [selected, setSelected] = useState<string | null>(null);
  const [file, setFile] = useState<{ path: string; content?: string; size?: number } | null>(null);
  const [content, setContent] = useState("");
  const [fileLoading, setFileLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [preview, setPreview] = useState(true);
  const [loadingDir, setLoadingDir] = useState<Set<string>>(new Set());

  // 新建弹窗
  const [showNewFile, setShowNewFile] = useState(false);
  const [showNewDir, setShowNewDir] = useState(false);
  const [newPath, setNewPath] = useState("");
  const [newDirPath, setNewDirPath] = useState("");
  const [opError, setOpError] = useState("");

  // 初始化加载根目录
  useEffect(() => {
    if (targetId) loadDir("");
  }, [targetId, mode]);

  /** 加载目录子节点 */
  const loadDir = useCallback(async (dirPath: string) => {
    if (!targetId) return;
    setLoadingDir(prev => new Set([...prev, dirPath]));
    try {
      const entries = await api.getTree(targetId, dirPath);
      setTreeMap(prev => ({ ...prev, [dirPath]: entries }));
    } catch { /* ignore */ } finally {
      setLoadingDir(prev => { const n = new Set(prev); n.delete(dirPath); return n; });
    }
  }, [targetId, api]);

  /** 展开/折叠目录 */
  const toggleDir = useCallback((path: string) => {
    setExpanded(prev => {
      const next = new Set(prev);
      if (next.has(path)) { next.delete(path); return next; }
      next.add(path);
      if (!treeMap[path]) loadDir(path);
      return next;
    });
  }, [treeMap, loadDir]);

  /** 选择文件 */
  const selectFile = useCallback(async (path: string) => {
    if (!targetId) return;
    setSelected(path);
    setPreview(path.toLowerCase().endsWith(".md"));
    setFileLoading(true);
    try {
      const detail = await api.getFile(targetId, path);
      setFile(detail);
      setContent(detail.content || "");
    } catch { setFile(null); } finally { setFileLoading(false); }
  }, [targetId, api]);

  /** 保存文件 */
  const saveCurrentFile = useCallback(async () => {
    if (!targetId || !selected) return;
    setSaving(true);
    try {
      await api.saveFile(targetId, selected, content);
      setFile(p => p ? { ...p, content } : null);
    } finally { setSaving(false); }
  }, [targetId, selected, content, api]);

  /** 下载文件 */
  const downloadCurrentFile = useCallback(async () => {
    if (!targetId || !selected) return;
    const name = selected.split("/").pop() || "download";
    await api.downloadFile(targetId, selected, name);
  }, [targetId, selected, api]);

  /** 父目录路径 */
  const parentDir = (childPath: string) => {
    const idx = childPath.lastIndexOf("/");
    return idx >= 0 ? childPath.slice(0, idx) : "";
  };

  /** 当前选中节点的父目录 */
  const getParentPath = (): string => {
    if (!selected) return "";
    if (selected.endsWith("/")) return selected;
    const idx = selected.lastIndexOf("/");
    return idx >= 0 ? selected.slice(0, idx + 1) : "";
  };

  /** 新建文件 */
  const createFile = useCallback(async () => {
    if (!targetId || !newPath.trim()) return;
    setOpError("");
    const name = newPath.trim().replace(/^\/+/, "");
    const fullPath = getParentPath() + name;
    try {
      await api.saveFile(targetId, fullPath, "");
      setShowNewFile(false); setNewPath("");
      loadDir(parentDir(fullPath));
    } catch (e: any) { setOpError(e?.message || "创建失败"); }
  }, [targetId, newPath, api, loadDir, selected]);

  /** 新建目录 */
  const createDirectory = useCallback(async () => {
    if (!targetId || !newDirPath.trim()) return;
    setOpError("");
    const name = newDirPath.trim().replace(/^\/+|\/+$/g, "");
    const fullPath = getParentPath() + name + "/";
    try {
      await api.createDir(targetId, fullPath);
      setShowNewDir(false); setNewDirPath("");
      loadDir(parentDir(fullPath));
    } catch (e: any) { setOpError(e?.message || "创建失败"); }
  }, [targetId, newDirPath, api, loadDir, selected]);

  /** 删除节点 */
  const deleteNode = useCallback(async (entry: WorkspaceNode) => {
    if (!targetId) return;
    const label = entry.path || entry.name || "";
    if (!confirm(`确定删除「${label}」？不可撤销。`)) return;
    const p = entry.path || "";
    try {
      if (entry.type === "dir") await api.deleteDir(targetId, p, true);
      else await api.deleteFile(targetId, p);
      if (selected === p) { setSelected(null); setFile(null); setContent(""); }
      setTreeMap(prev => { const n = { ...prev }; delete n[p]; return n; });
      loadDir(parentDir(p));
    } catch { /* ignore */ }
  }, [targetId, selected, api, loadDir]);

  const isMd = selected?.toLowerCase().endsWith(".md");

  /** 递归渲染树节点 */
  const renderNode = (entry: WorkspaceNode, depth: number): React.ReactNode => {
    const p = entry.path || "";
    const isDir = entry.type === "dir";
    const isExpanded = expanded.has(p);
    const isSelected = selected === p;
    const isLoading = loadingDir.has(p);
    const children = treeMap[p] || [];

    return (
      <div key={p}>
        <div
          className={`group flex items-center gap-1.5 py-0.5 px-2 rounded cursor-pointer text-sm hover:bg-accent/60 ${isSelected ? "bg-accent" : ""}`}
          style={{ paddingLeft: `${depth * 12 + 8}px` }}
          onClick={() => isDir ? toggleDir(p) : selectFile(p)}
        >
          {isDir ? (
            isLoading
              ? <Loader2 className="h-3 w-3 shrink-0 animate-spin text-muted-foreground" />
              : <ChevronRight className={`h-3 w-3 shrink-0 text-muted-foreground transition ${isExpanded ? "rotate-90" : ""}`} />
          ) : <span className="w-3 shrink-0" />}
          {isDir ? (isExpanded ? <FolderOpen className="h-3.5 w-3.5 shrink-0 text-blue-500" /> : <Folder className="h-3.5 w-3.5 shrink-0 text-blue-500" />)
            : <File className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />}
          <span className="truncate text-xs">{entry.name}</span>
          <button className="ml-auto opacity-0 group-hover:opacity-60 hover:!opacity-100"
            onClick={e => { e.stopPropagation(); deleteNode(entry); }} title="删除">
            <Trash2 className="h-3 w-3" />
          </button>
        </div>
        {isDir && isExpanded && children
          .sort((a, b) => {
            if (a.type !== b.type) return a.type === "dir" ? -1 : 1;
            return (a.name || "").localeCompare(b.name || "");
          })
          .map(child => renderNode(child, depth + 1))}
      </div>
    );
  };

  return (
    <div className={`flex h-full border rounded-lg overflow-hidden relative ${className || ""}`}>
      {/* 左侧：文件树 */}
      <div className="w-56 shrink-0 border-r bg-background flex flex-col min-h-0">
        <div className="flex items-center justify-between px-3 py-2 border-b shrink-0">
          <span className="text-xs font-medium text-muted-foreground">文件</span>
          <div className="flex gap-0.5">
            <Button variant="ghost" size="icon" className="h-6 w-6" title="新建文件" onClick={() => setShowNewFile(true)}>
              <FilePlus className="h-3.5 w-3.5" />
            </Button>
            <Button variant="ghost" size="icon" className="h-6 w-6" title="新建目录" onClick={() => setShowNewDir(true)}>
              <FolderPlus className="h-3.5 w-3.5" />
            </Button>
          </div>
        </div>
        <div className="flex-1 min-h-0 overflow-auto">
          <div className="min-w-max">
            {(() => {
              const rootEntries = treeMap[""] || [];
              return rootEntries.length === 0 ? (
                <p className="text-xs text-muted-foreground text-center py-8">暂无文件</p>
              ) : (
                <div className="py-1">
                  {[...rootEntries].sort((a, b) => {
                    if (a.type !== b.type) return a.type === "dir" ? -1 : 1;
                    return (a.name || "").localeCompare(b.name || "");
                  }).map(entry => renderNode(entry, 0))}
                </div>
              );
            })()}
          </div>
        </div>
      </div>

      {/* 右侧：编辑器/预览 */}
      <div className="flex-1 flex flex-col min-w-0 min-h-0">
        <div className="flex items-center justify-between px-3 py-2 border-b bg-muted/20 shrink-0">
          <span className="text-xs text-muted-foreground truncate max-w-[60%]">
            {selected || "未选择文件"}
          </span>
          <div className="flex items-center gap-1">
            {isMd && selected && (
              <Button size="sm" variant="ghost" className="h-7 text-xs" onClick={() => setPreview(!preview)}>
                {preview ? <><Pencil className="h-3 w-3 mr-1" />编辑</> : <><Eye className="h-3 w-3 mr-1" />预览</>}
              </Button>
            )}
            {selected && (
              <Button size="sm" variant="outline" className="h-7 text-xs" onClick={saveCurrentFile} disabled={saving}>
                {saving ? <Loader2 className="h-3 w-3 animate-spin mr-1" /> : <Save className="h-3 w-3 mr-1" />}
                保存
              </Button>
            )}
            {selected && (
              <Button size="sm" variant="ghost" className="h-7 text-xs" onClick={downloadCurrentFile}>
                <Download className="h-3 w-3 mr-1" />下载
              </Button>
            )}
          </div>
        </div>
        <div className="flex-1 min-h-0">
          {fileLoading ? (
            <div className="flex items-center justify-center h-full">
              <Loader2 className="h-5 w-5 animate-spin text-muted-foreground" />
            </div>
          ) : file ? (
            isMd && preview ? (
              <ScrollArea className="h-full">
                <div
                  className="p-4 prose prose-sm dark:prose-invert max-w-none overflow-hidden"
                  dangerouslySetInnerHTML={{ __html: renderMarkdown(content) }}
                />
              </ScrollArea>
            ) : (
              <Textarea
                value={content}
                onChange={e => setContent(e.target.value)}
                placeholder="文件内容为空"
                className="w-full h-full resize-none border-0 rounded-none font-mono text-sm p-4 focus-visible:ring-0"
                style={{ tabSize: 2 }}
              />
            )
          ) : selected ? (
            <div className="flex items-center justify-center h-full text-sm text-muted-foreground">文件内容为空</div>
          ) : (
            <div className="flex items-center justify-center h-full text-sm text-muted-foreground">选择文件查看内容</div>
          )}
        </div>
      </div>

      {/* 新建文件弹窗 */}
      {showNewFile && (
        <div className="absolute inset-0 z-10 flex items-center justify-center bg-background/80" onClick={() => setShowNewFile(false)}>
          <div className="w-80 p-4 rounded-lg border bg-card shadow-lg" onClick={e => e.stopPropagation()}>
            <h3 className="text-sm font-medium mb-3">新建文件</h3>
            <div className="space-y-3">
              <div className="space-y-1">
                <Label className="text-xs">文件名</Label>
                <Input placeholder="例如: config.yaml" className="h-8 text-sm font-mono" value={newPath}
                  onChange={e => setNewPath(e.target.value)} autoFocus
                  onKeyDown={e => { if (e.key === "Enter") createFile(); if (e.key === "Escape") setShowNewFile(false); }} />
              </div>
              {opError && <p className="text-xs text-destructive">{opError}</p>}
              <div className="flex gap-2 justify-end">
                <Button variant="ghost" size="sm" onClick={() => { setShowNewFile(false); setNewPath(""); setOpError(""); }}>取消</Button>
                <Button size="sm" onClick={createFile} disabled={!newPath.trim()}>创建</Button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* 新建目录弹窗 */}
      {showNewDir && (
        <div className="absolute inset-0 z-10 flex items-center justify-center bg-background/80" onClick={() => setShowNewDir(false)}>
          <div className="w-80 p-4 rounded-lg border bg-card shadow-lg" onClick={e => e.stopPropagation()}>
            <h3 className="text-sm font-medium mb-3">新建目录</h3>
            <div className="space-y-3">
              <div className="space-y-1">
                <Label className="text-xs">目录名</Label>
                <Input placeholder="例如: scripts" className="h-8 text-sm font-mono" value={newDirPath}
                  onChange={e => setNewDirPath(e.target.value)} autoFocus
                  onKeyDown={e => { if (e.key === "Enter") createDirectory(); if (e.key === "Escape") setShowNewDir(false); }} />
              </div>
              {opError && <p className="text-xs text-destructive">{opError}</p>}
              <div className="flex gap-2 justify-end">
                <Button variant="ghost" size="sm" onClick={() => { setShowNewDir(false); setNewDirPath(""); setOpError(""); }}>取消</Button>
                <Button size="sm" onClick={createDirectory} disabled={!newDirPath.trim()}>创建</Button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

/**
 * 简易 Markdown → HTML 渲染
 */

export function renderMarkdown(md: string): string {
  if (!md) return '';

  let html = md
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

  html = html
    .replace(/```(\w*)\n([\s\S]*?)```/g, '<pre class="bg-muted rounded-md p-3 text-xs font-mono overflow-x-auto whitespace-pre-wrap break-all"><code>$2</code></pre>')
    .replace(/`([^`]+)`/g, '<code class="bg-muted px-1 rounded text-xs font-mono">$1</code>')
    .replace(/^\|(.+)\|\s*\n\|[-| :]+\|\s*\n((?:^\|.+\|\s*\n?)*)/gm, (_match, header, body) => {
      const thead = header.split('|').map((h: string) =>
        `<th class="border px-3 py-1.5 text-left text-xs font-semibold bg-muted/50">${h.trim()}</th>`
      ).join('');
      const rows = body.trim().split('\n').map((row: string) => {
        const cells = row.replace(/^\||\|$/g, '').split('|').map((c: string) =>
          `<td class="border px-3 py-1 text-xs">${c.trim()}</td>`
        ).join('');
        return `<tr>${cells}</tr>`;
      }).join('');
      return `<div class="overflow-x-auto my-3"><table class="w-full border-collapse border"><thead><tr>${thead}</tr></thead><tbody>${rows}</tbody></table></div>`;
    })
    .replace(/^#### (.+)$/gm, '<h4 class="text-sm font-semibold mt-4 mb-1">$1</h4>')
    .replace(/^### (.+)$/gm, '<h3 class="text-base font-semibold mt-4 mb-1">$1</h3>')
    .replace(/^## (.+)$/gm, '<h2 class="text-lg font-semibold mt-4 mb-2">$1</h2>')
    .replace(/^# (.+)$/gm, '<h1 class="text-xl font-bold mt-4 mb-2">$1</h1>')
    .replace(/\*\*\*(.+?)\*\*\*/g, '<strong><em>$1</em></strong>')
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/\*(.+?)\*/g, '<em>$1</em>')
    .replace(/^[*-] (.+)$/gm, '<li class="ml-4 list-disc">$1</li>')
    .replace(/^\d+\. (.+)$/gm, '<li class="ml-4 list-decimal">$1</li>')
    .replace(/^> (.+)$/gm, '<blockquote class="border-l-2 border-muted-foreground/30 pl-3 italic text-muted-foreground">$1</blockquote>')
    .replace(/^---$/gm, '<hr class="my-4 border-border" />')
    .replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" class="text-primary underline" target="_blank" rel="noreferrer">$1</a>')
    .replace(/\n\n/g, '</p><p class="mb-2">')
    .replace(/\n/g, '<br/>');

  return `<div class="prose prose-sm max-w-none"><p class="mb-2">${html}</p></div>`;
}

/**
 * 工作区文件类型
 * 对齐后端 /agents/{id}/workspace 和 /tasks/{id}/workspace 接口
 */

/** 工作区模式 */
export type WorkspaceMode = 'agent' | 'task';

// ======== Agent 模式类型（向后兼容） ========

/** 文件树节点（agent 模式） */
export interface AgentWorkspaceFileEntry {
  name?: string;
  path?: string;
  size?: number;
  type?: 'file' | 'dir';
  updatedAt?: string;
}

/** 文件详情（agent 模式） */
export interface AgentWorkspaceFileDetail {
  content?: string;
  contentType?: string;
  name?: string;
  path?: string;
  size?: number;
  type?: 'file';
  updatedAt?: string;
}

/** 创建目录请求（agent 模式） */
export interface CreateAgentWorkspaceDirRequest {
  path: string;
}

/** 保存文件请求（agent 模式） */
export interface SaveAgentWorkspaceFileRequest {
  path: string;
  content?: string;
}

// ======== Task 模式类型 ========

/** 文件树节点（task 模式原始类型） */
export interface TaskWorkspaceEntry {
  name: string;
  path: string;
  isDir: boolean;
  size?: number;
  updatedAt?: string;
}

/** 文件详情（task 模式） */
export interface TaskWorkspaceFile {
  path: string;
  content?: string;
  size?: number;
  contentType?: string;
  updatedAt?: string;
}

// ======== 统一内部类型（组件使用） ========

/** 统一的文件树节点（归一化后） */
export interface WorkspaceNode {
  name: string;
  path: string;
  type: 'file' | 'dir';
  size?: number;
  updatedAt?: string;
}

/** 统一的文件详情（归一化后） */
export interface WorkspaceFileDetail {
  path: string;
  content?: string;
  size?: number;
  contentType?: string;
  updatedAt?: string;
}

// ======== API 接口定义 ========

export interface WorkspaceApi {
  getTree(id: string, path?: string): Promise<WorkspaceNode[]>;
  getFile(id: string, path: string): Promise<WorkspaceFileDetail>;
  saveFile(id: string, path: string, content: string): Promise<void>;
  deleteFile(id: string, path: string): Promise<void>;
  createDir(id: string, path: string): Promise<void>;
  deleteDir(id: string, path: string, recursive?: boolean): Promise<void>;
  downloadFile(id: string, path: string, filename?: string): Promise<void>;
}

/**
 * 工作区 API 客户端
 * agent 模式: /eap/agents/{id}/workspace/*  (type: 'file'/'dir')
 * task  模式: /eap/tasks/{id}/workspace/*   (isDir: boolean)
 * 两者接口结构完全一致，仅 base path 和返回字段名不同。
 */

import { createAPI } from '@kesi/client';
import type { WorkspaceMode, WorkspaceNode, WorkspaceFileDetail, WorkspaceApi } from './types';

const apis = {
  agent: createAPI({ name: 'eap/agents' }),
  task:  createAPI({ name: 'eap/tasks' }),
};

/** 归一化：{type:'dir'} 或 {isDir:true} → WorkspaceNode */
function normalizeEntry(raw: any): WorkspaceNode {
  return {
    name: raw.name || '',
    path: raw.path || '',
    type: (raw.type === 'dir' || raw.isDir) ? 'dir' : 'file',
    size: raw.size,
    updatedAt: raw.updatedAt,
  };
}

/** 归一化文件详情 */
function normalizeFile(raw: any): WorkspaceFileDetail {
  return {
    path: raw.path || '',
    content: raw.content,
    size: raw.size,
    contentType: raw.contentType,
    updatedAt: raw.updatedAt,
  };
}

/**
 * 创建统一工作区 API
 * @param mode - 'agent' | 'task'
 */
export function createWorkspaceApi(mode: WorkspaceMode): WorkspaceApi {
  const api = apis[mode];
  const base = mode === 'agent' ? 'agents' : 'tasks';

  const asJson = <T>(r: any): T => r?.json ?? r;

  return {
    /** GET /{id}/workspace/tree[?path=...] */
    async getTree(id: string, path = '') {
      const q = path ? `?path=${encodeURIComponent(path)}` : '';
      const data = asJson<any>(await api.fetch(`/${id}/workspace/tree${q}`));
      const entries = Array.isArray(data) ? data : (data?.entries || []);
      return entries.map(normalizeEntry);
    },

    /** GET /{id}/workspace/file?path=... */
    async getFile(id: string, path: string) {
      const q = `?path=${encodeURIComponent(path)}`;
      return normalizeFile(asJson<any>(await api.fetch(`/${id}/workspace/file${q}`)));
    },

    /** PUT /{id}/workspace/file */
    async saveFile(id: string, path: string, content: string) {
      await api.fetch(`/${id}/workspace/file`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ path, content }),
      });
    },

    /** DELETE /{id}/workspace/file?path=... */
    async deleteFile(id: string, path: string) {
      await api.fetch(`/${id}/workspace/file?path=${encodeURIComponent(path)}`, { method: 'DELETE' });
    },

    /** POST /{id}/workspace/dirs */
    async createDir(id: string, path: string) {
      await api.fetch(`/${id}/workspace/dirs`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ path }),
      });
    },

    /** DELETE /{id}/workspace/dirs?path=...&recursive=... */
    async deleteDir(id: string, path: string, recursive = false) {
      await api.fetch(`/${id}/workspace/dirs?path=${encodeURIComponent(path)}&recursive=${recursive}`, { method: 'DELETE' });
    },

    /** 下载文件 */
    async downloadFile(id: string, path: string, filename?: string) {
      const cleanPath = path.replace(/^\/?(workspace\/)?[a-f0-9]{24}\/?/, '');
      const params = new URLSearchParams({ path: cleanPath });
      const authHeader = api.headers?.['Authorization'] || api.headers?.authorization || '';
      const projectId = api.headers?.['x-request-project'] || '';
      if (authHeader) params.set('token', authHeader.replace(/^Bearer\s+/i, ''));
      if (projectId) params.set('x-request-project', projectId);
      const url = `/rest/eap/${base}/${id}/workspace/file/download?${params.toString()}`;
      const a = document.createElement('a');
      a.href = url;
      a.download = filename || path.split('/').pop() || 'download';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
    },
  };
}
